// GENERATED by scripts/sync-shared.ts from shared/band.tsx. Edit shared/, not this copy.
// Band composition (conventions s4): segments -> one row per plugin, AbovePrompt hook helper.
import type { EngineInterface } from 'claude-code'
import { BAND_H, SEG_GAP } from './tokens'
import { svgDoc } from './svgkit'
import { clamp } from './fmt'

/** One width choice of a segment. `svg` is a fragment 30 px high at origin 0,0 (no <svg> wrapper, no tokens style). */
export type Variant = {
  px: number
  cells: number
  svg: string
  /** Terminal string. */
  text: string
  /** Same string as `text` without colour (the Svg alt). */
  alt: string
  /** Terminal colour for the whole segment text; `dim` renders dimColor. */
  color?: string
  dim?: boolean
}
/** `variants[0]` is the widest. Lower `priority` number = more important (shrunk/dropped last). */
export type Segment = { id: string; order: number; priority: number; pinned?: boolean; variants: Variant[] }
export type Row = { svg: string; alt: string; text: string; width: number; ids: string[]; cellsUsed: number }

type Pick = { seg: Segment; i: number }

/** Shrink-then-drop algorithm over one measure. Returns the surviving picks (in `order`). */
function fitPicks(segs: Segment[], limit: number, gap: number, size: (v: Variant) => number): Pick[] {
  let picks: Pick[] = segs.map(seg => ({ seg, i: 0 }))
  const total = (): number => picks.reduce((n, p) => n + size(p.seg.variants[p.i] as Variant), 0) + gap * Math.max(0, picks.length - 1)
  // Largest priority number first; later order first on ties.
  const worst = (xs: Pick[]): Pick | undefined => [...xs].sort((a, b) => b.seg.priority - a.seg.priority || b.seg.order - a.seg.order)[0]
  while (picks.length > 0 && total() > limit) {
    const shrinkable = picks.filter(p => p.i < p.seg.variants.length - 1)
    const s = worst(shrinkable)
    if (s) { s.i++; continue }
    const droppable = worst(picks.filter(p => !p.seg.pinned))
    if (!droppable) break
    picks = picks.filter(p => p !== droppable)
  }
  // Grow-back (F28): spend leftover room. Widen the most important segment that has a wider variant; then re-add
  // dropped segments (in `order`) at their narrowest variant. Never exceeds the limit.
  if (total() <= limit) {
    for (;;) {
      const ups = picks.filter(p => p.i > 0).sort((a, b) => a.seg.priority - b.seg.priority || a.seg.order - b.seg.order)
      let moved = false
      for (const p of ups) {
        p.i--
        if (total() <= limit) { moved = true; break }
        p.i++
      }
      if (moved) continue
      const gone = segs.filter(s => !picks.some(p => p.seg === s)).sort((a, b) => a.order - b.order)
      for (const seg of gone) {
        const back: Pick = { seg, i: seg.variants.length - 1 }
        picks.push(back)
        if (total() <= limit) { moved = true; break }
        picks.pop()
      }
      if (!moved) break
    }
  }
  return picks.sort((a, b) => a.seg.order - b.seg.order)
}

/**
 * composeRow(segments, W, cols): drop nulls; every segment starts at variants[0]; while the total exceeds the
 * limit move the lowest-priority shrinkable segment to its next variant, else drop the lowest-priority
 * non-pinned segment. Desktop fit uses px (+12 px gaps) against W; terminal fit uses cells (+2 gap) against cols.
 * The two fits are independent, so `alt` equals `text` whenever both pick the same variants (true when both fit).
 * Returns null when nothing survives.
 */
export function composeRow(segments: readonly (Segment | null | undefined)[], W: number, cols: number): Row | null {
  const segs = segments.filter((s): s is Segment => !!s && s.variants.length > 0)
  if (segs.length === 0) return null
  const px = fitPicks(segs, W, SEG_GAP, v => v.px)
  const tx = fitPicks(segs, cols, 2, v => v.cells)
  if (px.length === 0 && tx.length === 0) return null
  let x = 0
  let body = ''
  for (const p of px) {
    const v = p.seg.variants[p.i] as Variant
    body += `<g transform="translate(${x},0)">${v.svg}</g>`
    x += v.px + SEG_GAP
  }
  const width = Math.max(1, x - SEG_GAP)
  const alt = px.map(p => (p.seg.variants[p.i] as Variant).alt).join('  ')
  const text = tx.map(p => (p.seg.variants[p.i] as Variant).text).join('  ')
  return {
    svg: svgDoc(width, BAND_H, body),
    alt,
    text,
    width,
    ids: px.map(p => p.seg.id),
    cellsUsed: tx.reduce((n, p) => n + (p.seg.variants[p.i] as Variant).cells, 0) + 2 * Math.max(0, tx.length - 1),
  }
}

/** Desktop band width: clamp(bodyColumns*8 - reserved, 180, 1600) as in agent-pets. */
export const bandWidth = (bodyColumns: number, reservePx = 16): number => clamp((bodyColumns || 100) * 8 - reservePx, 180, 1600)

type Next = (e: any) => Promise<any>
/** Ports renderBand needs; register.tsx builds them from `$`: `{ resolve: e => $.ui.resolve(e) }`. */
export type BandPorts = { resolve: (e: any) => any }
export type BandOpts = {
  /** The segments, or a function evaluated after the survey / agent-view / row gates (lazy work). */
  segments: readonly (Segment | null | undefined)[] | (() => readonly (Segment | null | undefined)[] | Promise<readonly (Segment | null | undefined)[]>)
  /** Option `minBandRows`, default 4: below it the plugin is silent. */
  minBandRows?: number
  /** Pressable elements beside the Svg on desktop (pets button, dismiss). Already-built nodes. Also puts the terminal Text in a row Box. */
  buttons?: unknown[]
  /** px reserved for those buttons. */
  reservePx?: number
  /** Skip the main-view check (never needed). */
  allowAgentView?: boolean
  /** The desktop Svg sits directly in the column (no wrapping row Box). Default false. */
  flat?: boolean
  /** A throwing `next(e)` counts as an engine-only inner (usage). Default false. */
  tolerantNext?: boolean
  /** Use `e.viewport.columns` when `props.bodyColumns` is unset (usage). Default false. */
  viewportFallback?: boolean
}

/**
 * The band line itself (pure): desktop Svg (or the terminal Text), with optional buttons. `row` may be null when
 * only buttons exist. `t` is the resolved component set (`ports.resolve(e)`).
 */
export function bandLine(t: any, surface: string | undefined | null, row: Row | null, o: { flat?: boolean; buttons?: unknown[] } = {}): any {
  const { Box, Text } = t
  if (surface !== 'terminal' && 'Svg' in t) {
    const { Svg } = t
    if (o.flat) return <Svg source={(row as Row).svg} alt={(row as Row).alt} width={(row as Row).width} height={BAND_H} />
    return (
      <Box flexDirection="row" alignItems="center" gap={1}>
        {row && <Svg source={row.svg} alt={row.alt} width={row.width} height={BAND_H} />}
        {o.buttons}
      </Box>
    )
  }
  if (o.buttons !== undefined) {
    return (
      <Box flexDirection="row" gap={1}>
        {row && <Text wrap="truncate-end">{row.text}</Text>}
        {o.buttons}
      </Box>
    )
  }
  return <Text wrap="truncate-end">{(row as Row).text}</Text>
}

/** `<Box column>{below}{line}</Box>` where `below` is `inner` unless it is the engine placeholder. */
export function bandStack(t: any, inner: any, line: any): any {
  const { Box } = t
  const below = inner && inner.type === 'engine' ? null : inner
  return (
    <Box flexDirection="column">
      {below}
      {line}
    </Box>
  )
}

/**
 * The AbovePrompt pattern (agent-pets register.tsx): `inner = await next(e)`; return `inner` for a survey, an
 * agent view, too few rows, or no segment; else `<Box column>{below}{row}</Box>`.
 * Use as: `on('ui.render', {component:'AbovePrompt'}, ($, e, next) => renderBand({ resolve: x => $.ui.resolve(x) }, e, next, {segments}))`.
 */
export async function renderBand(ports: BandPorts, e: any, next: Next, o: BandOpts): Promise<any> {
  let inner: any
  if (o.tolerantNext) {
    try { inner = await next(e) } catch { inner = { type: 'engine' } }
  } else inner = await next(e)
  if (e.props?.hasSurvey) return inner
  if (!o.allowAgentView && e.props?.view?.agentId) return inner
  if (e.props?.maxRows < (o.minBandRows ?? 4)) return inner
  const segments = typeof o.segments === 'function' ? await o.segments() : o.segments
  const bodyCols = o.viewportFallback ? e.props?.bodyColumns || e.viewport?.columns || 0 : e.props?.bodyColumns
  const cols = Math.max(20, bodyCols || 60)
  const row = composeRow(segments, bandWidth(bodyCols, o.reservePx ?? (o.buttons?.length ? 130 : 16)), cols)
  if (!row) return inner
  const t: any = ports.resolve(e)
  return bandStack(t, inner, bandLine(t, e.surface, row, { flat: o.flat, buttons: o.buttons }))
}
